        {"source": "schematic", "quote": "J7 AVR-ISP-6 ... MISO 1 NET0011, MOSI 4 NET0010, SCK 5 NET0003, RST 3 NET0012"},
        {"source": "schematic", "quote": "U3 ATtiny45-20P ... pin 1 NET0012 ... pin 7 NET0003; U2 ATtiny13V-10S ... pin 1 NET0012 ... pin 7 NET0003"}
      ],
      "impact": "A standard AVR ISP programmer connected to this header would have SCK and RESET interchanged, preventing normal programming and possibly leaving the MCU reset line driven by the wrong header pin.",
      "confidence": 0.75
    },
    {
      "category": "bridged_nets",
      "components": ["U4"],
      "pins": ["U4.VI", "U4.V0"],
      "nets": ["+5V", "VCC"],
      "observed": "U4 LM1117-5.0 is shown with both its VI input pin and V0 output pin connected to the +5V net; the VCC rail is not connected to the regulator input.",
      "expected": "For an LM1117-5.0 regulator, VI should be connected to the higher unregulated VCC rail and V0 should be the regulated +5V output.",
      "evidence": [
        {"source": "schematic", "quote": "U4 LM1117-5.0 ... +5V on VI and +5V on V0, pin 1 GND"},
        {"source": "schematic", "quote": "VCC appears on C3, R8, JP2 and Q3, not on U4"}
      ],
      "impact": "The 5V rail is not regulated from VCC; if VCC is the board power input, the +5V/MCU rail would not be powered from it and the regulator is effectively bypassed or misconnected.",
      "confidence": 0.62
    }
